#!/usr/bin/env bash
# DROIT À L'IMAGE — incrément 1 (backend) :
#   - majorité et parent référent (création de compte, setLegalInfo) ; date de naissance vérifiée non modifiable ;
#   - formulaire du club rempli par le serveur (pdf-lib) : pré-rempli, ou récapitulatif d'une autorisation en ligne ;
#   - confirmation en ligne du membre majeur (mot de passe redemandé) ; avis à contact@ à chaque version.
# Ajoute la dépendance pdf-lib (pnpm add).
# Prérequis : apply-colonne-formulaire.sh.
# Usage (racine du repo) : bash apply-droit-image-backend.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" 2>/dev/null | grep -qF "export async function confirmMemberConsent"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "IMAGE_CONSENT_PROOF_LABEL" "packages/contracts/src/legal/imageConsent.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-colonne-formulaire.sh"; exit 1; }
MODIFIED=("apps/web/src/features/admin/users/forms/update-me/updateMeForm.action.ts" "packages/backend/src/modules/imageConsent/imageConsentForm.service.ts" "packages/backend/src/modules/imageConsent/router.ts" "packages/backend/src/modules/privacy/exportMyData.service.ts" "packages/backend/src/modules/users/router.ts" "packages/contracts/src/legal/imageConsent.ts")
CREATED=("apps/web/src/app/api/media/image-consent/prefilled/route.ts" "packages/backend/src/email/templates/imageConsentNotice.ts" "packages/backend/src/modules/imageConsent/consentPdf.service.ts" "packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" "packages/backend/src/modules/users/legalInfo.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/src/app/api/media/image-consent/prefilled" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "export async function confirmMemberConsent" "packages/backend/src/modules/imageConsent/imageConsentOnline.service.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

mkdir -p "apps/web/src/app/api/media/image-consent/prefilled"
